import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.v1TqQkD7.js";const u=JSON.parse('{"title":"Security Controls","description":"","frontmatter":{"title":"Security Controls","sourceFile":"guides/SECURITY.md"},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md"}'),i={name:"guide/security.md"};function r(n,e,d,c,h,l){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="security-controls" tabindex="-1">Security Controls <a class="header-anchor" href="#security-controls" aria-label="Permalink to &quot;Security Controls&quot;">​</a></h1><p><strong>Implements:</strong> SEC-01, SEC-02, SEC-03, SEC-04, SEC-05, SEC-06, SEC-07, SEC-08 — see <a href="./charter#part-6--security">CHARTER.md</a></p><p>How ESI.ts defends a consumer at runtime and how the repository defends the package on its way to a registry. The disclosure policy (supported versions, how to report, response timeline, scope) lives in the root <a href="https://github.com/lgriffin/ESI.ts/blob/master/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> and is not repeated here.</p><p>Runtime defences live in the request pipeline and are proven by unit tests. Supply-chain defences live in the workflows and are scored weekly. They are one posture.</p><hr><h2 id="1-runtime-defence-chain" tabindex="-1">1. Runtime defence chain <a class="header-anchor" href="#1-runtime-defence-chain" aria-label="Permalink to &quot;1. Runtime defence chain&quot;">​</a></h2><p>Every request passes these checks in this order. The first two happen once, when the client is constructed; the rest happen per call.</p><table tabindex="0"><thead><tr><th>#</th><th>Control</th><th>Where</th><th>Behaviour</th></tr></thead><tbody><tr><td>1</td><td>HTTPS enforced</td><td><code>validateBaseUrl</code> in <code>src/core/util/validation.ts</code></td><td>A base URL whose protocol is not <code>https:</code> throws at construction. There is no flag to disable this.</td></tr><tr><td>2</td><td>Host allowlisted</td><td>same</td><td>Only <code>esi.evetech.net</code> is allowed. Any other host throws unless <code>unsafeAllowCustomHost: true</code> is set.</td></tr><tr><td>3</td><td>Path parameters checked</td><td><code>validatePathParam</code>, called from <code>buildEndpointPath</code></td><td>Rejects empty values, non-finite numbers and any of <code>/ \\ ? # @ ! $ &amp; &#39; ( ) * + , ; = &lt; &gt; { } | ^</code> and backtick. The value is then <code>encodeURIComponent</code>-encoded.</td></tr><tr><td>4</td><td>Query parameters bounded</td><td><code>validateQueryParam</code>, called from <code>buildEndpointPath</code></td><td>Rejects <code>null</code>, non-finite numbers and values longer than 2000 characters. The value is then encoded.</td></tr><tr><td>5</td><td>Token gated by the definition</td><td><code>buildRequestHeaders</code> in <code>src/core/requestPipeline/headers.ts</code></td><td>The <code>Authorization</code> header is attached only when the endpoint definition sets <code>requiresAuth</code>. A missing token throws <code>NO_AUTH_TOKEN</code> before any network call.</td></tr><tr><td>6</td><td>URLs sanitised in errors</td><td><code>sanitizeUrl</code> in <code>src/core/util/error.ts</code></td><td><code>EsiError.url</code> and the <code>EsiValidationError</code> message pass through it. See below.</td></tr></tbody></table><p>All validation failures throw an <code>Error</code> typed <code>VALIDATION_ERROR</code>. The error family is described in <a href="./errors">ERRORS.md</a>.</p><h3 id="construction" tabindex="-1">Construction <a class="header-anchor" href="#construction" aria-label="Permalink to &quot;Construction&quot;">​</a></h3><p><code>EsiClient</code>, <code>EsiClientBuilder</code> and <code>EsiApiFactory</code> all call <code>validateBaseUrl</code> with the configured <code>baseUrl</code>, falling back to <code>ESI_BASE_URL</code> and then <code>https://esi.evetech.net</code>. <code>unsafeAllowCustomHost</code> relaxes the host check only. It exists for test servers and proxies, and its name is meant to show up in code review.</p><h3 id="path-and-query-encoding" tabindex="-1">Path and query encoding <a class="header-anchor" href="#path-and-query-encoding" aria-label="Permalink to &quot;Path and query encoding&quot;">​</a></h3><p>The unsafe-character check and the encoding step do different jobs. The check refuses values that would change the route (<code>../</code>, <code>?</code>, <code>#</code>, <code>@</code>). The encoding step neutralises anything else: a <code>%2f</code> or a null byte in a path parameter is not rejected, but it reaches ESI as a literal <code>%252f</code> or <code>%00</code> inside a single path segment and cannot introduce a new one.</p><h3 id="token-handling" tabindex="-1">Token handling <a class="header-anchor" href="#token-handling" aria-label="Permalink to &quot;Token handling&quot;">​</a></h3><ul><li>The bearer token is attached only where the definition declares <code>requiresAuth: true</code>. Public endpoints never see it, even when the client holds a token.</li><li><code>npm run validate:auth-scopes</code> checks that <code>requiresAuth</code> is set if and only if the generated scope map lists a scope for the endpoint (DES-04). A mismatch either leaks a token or breaks a call. See <a href="./design-rules">DESIGN-RULES.md</a>.</li><li>The token travels only in the <code>Authorization</code> header, never in a query string.</li><li><code>FileTokenStorage</code> in <code>src/auth/storage</code> writes to a sibling temporary file and renames it over the target, with POSIX mode <code>0o600</code> by default.</li></ul><h3 id="cache-isolation" tabindex="-1">Cache isolation <a class="header-anchor" href="#cache-isolation" aria-label="Permalink to &quot;Cache isolation&quot;">​</a></h3><p><code>buildCacheKey</code> in <code>src/core/cache/cacheKey.ts</code> returns the bare URL for public endpoints, so they share one cache entry. For an endpoint with <code>requiresAuth</code>, the key is prefixed with the caller&#39;s identity: <code>character:&lt;id&gt;</code> from the <code>sub</code> claim of an EVE SSO access token, or the first 16 hex characters of a SHA-256 hash of the <code>Authorization</code> header for a token that names no character. The claim is decoded, not verified, so it counts only once ESI has answered a request under that token with 2xx or 304 (<code>markTokenAccepted</code> in <code>cacheKey.ts</code>, called from <code>fetchExecution.ts</code>). Until then the token is keyed by its hash wherever an entry would be served without a request (the spec-TTL hit, stale-on-error, joining an in-flight request), and the character&#39;s ETag is sent only as <code>If-None-Match</code>: ESI&#39;s 304 accepts the token and serves the entry in one answer, and a 401 serves nothing. A forged token naming a character therefore reads none of that character&#39;s cache, two characters never share a cached body or ETag, a refreshed token keeps its character&#39;s entries, and the token never appears in a key in clear text.</p><h3 id="url-sanitisation" tabindex="-1">URL sanitisation <a class="header-anchor" href="#url-sanitisation" aria-label="Permalink to &quot;URL sanitisation&quot;">​</a></h3><p><code>sanitizeUrl</code> replaces the value of any of these query parameters with <code>[REDACTED]</code>: <code>token</code>, <code>access_token</code>, <code>api_key</code>, <code>refresh_token</code>, <code>client_secret</code>, <code>code</code>, <code>key</code>, <code>secret</code>, <code>auth</code>, <code>password</code>, <code>bearer</code>. If the URL cannot be parsed, everything after <code>?</code> is replaced with <code>[params-redacted]</code>. The function is exported from the root and from <code>@lgriffin/esi.ts/errors</code> for consumers who log URLs themselves.</p><p>Log lines pass through <code>sanitizeUrl</code> too, at the logger boundary: every URL in a line&#39;s message and top-level string context values is redacted before any logger, per-client or global, receives it. A custom request interceptor that adds a secret to the URL therefore sees <code>[REDACTED]</code> in the <code>Hitting endpoint: &lt;url&gt;</code> line, not the secret. Logging configuration and what is not redacted are covered in <a href="./logging#secrets-in-log-output">LOGGING.md</a>.</p><hr><h2 id="2-security-test-suite" tabindex="-1">2. Security test suite <a class="header-anchor" href="#2-security-test-suite" aria-label="Permalink to &quot;2. Security test suite&quot;">​</a></h2><p><code>tests/tdd/core/security.test.ts</code> is the executable form of the defence chain. Each <code>describe</code> group proves one control.</p><table tabindex="0"><thead><tr><th>Group</th><th>Proves</th></tr></thead><tbody><tr><td><code>Security: Token Handling</code></td><td>No <code>Authorization</code> header on a public endpoint; the header is present on an authenticated one</td></tr><tr><td><code>Security: HTTPS Enforcement</code></td><td><code>http://</code> is rejected by the client constructor and by <code>validateBaseUrl</code> directly</td></tr><tr><td><code>Security: Host Allowlist</code></td><td>Unknown hosts are rejected by default and accepted only with the unsafe flag</td></tr><tr><td><code>Security: Path Parameter Injection</code></td><td><code>../</code>, <code>?</code>, <code>#</code>, <code>\\</code>, <code>/</code> and <code>@</code> are rejected; ordinary IDs and names pass</td></tr><tr><td><code>Security: Query Parameter Length Limit</code></td><td>A query value over 2000 characters is rejected; one within the limit passes</td></tr><tr><td><code>Security: NaN/Infinity Path Params</code></td><td><code>NaN</code>, <code>Infinity</code> and <code>-Infinity</code> are rejected as path parameters</td></tr><tr><td><code>Security: Null/Empty Path Params</code></td><td><code>null</code>, <code>undefined</code> and the empty string are rejected as path parameters</td></tr></tbody></table><p>Controls tested outside that file:</p><table tabindex="0"><thead><tr><th>Control</th><th>Test file</th></tr></thead><tbody><tr><td>URL sanitisation</td><td><code>tests/tdd/core/error.test.ts</code>, <code>tests/tdd/core/EsiError.test.ts</code></td></tr><tr><td>Per-token cache keys</td><td><code>tests/tdd/core/cacheKey.test.ts</code>, <code>tests/tdd/core/requestPipeline/cachePolicy.test.ts</code></td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config/jest/unit.config.cjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tdd/core/security.test.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # includes the security suite</span></span></code></pre></div><hr><h2 id="3-supply-chain-hardening" tabindex="-1">3. Supply-chain hardening <a class="header-anchor" href="#3-supply-chain-hardening" aria-label="Permalink to &quot;3. Supply-chain hardening&quot;">​</a></h2><p>Which workflow runs at which stage, and whether it blocks, is set out in <a href="./quality-gates">QUALITY-GATES.md</a>. This section states what each control does.</p><h3 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Mechanism</th></tr></thead><tbody><tr><td>Actions pinned by SHA</td><td>Every <code>uses:</code> references a full 40-character commit SHA with the version as a trailing comment. A retagged upstream action cannot change what runs.</td></tr><tr><td>Least-privilege tokens</td><td>Every workflow declares top-level <code>permissions:</code> as <code>contents: read</code> (CodeQL declares <code>{}</code>; Scorecard <code>read-all</code>, as its action requires). Jobs escalate individually, for example <code>id-token: write</code> only on publish and signing jobs. <code>tests/tdd/workflows/workflow-permissions.test.ts</code> fails on a missing or writable top level and on any job-level write scope not in its list.</td></tr><tr><td>No credential persistence</td><td>Every checkout step sets <code>persist-credentials: false</code>.</td></tr><tr><td>No expression injection</td><td><code>run:</code> blocks read event data through <code>env:</code> bindings rather than interpolating <code>\${{ }}</code> into shell.</td></tr><tr><td>zizmor</td><td><code>zizmor.yml</code> audits <code>.github/</code> on any push or PR that touches workflows or <code>.zizmor.yml</code>. Accepted findings are listed with reasons in <code>.zizmor.yml</code>.</td></tr><tr><td>CodeQL</td><td><code>codeql.yml</code> on push and PR to <code>master</code>, and weekly.</td></tr><tr><td>OpenSSF Scorecard</td><td><code>scorecard.yml</code> weekly; results are published and uploaded as SARIF to code scanning.</td></tr><tr><td>Dependabot</td><td><code>.github/dependabot.yml</code> opens weekly PRs for npm dependencies and for GitHub Actions, which keeps pinned SHAs current.</td></tr></tbody></table><h3 id="dependency-advisories" tabindex="-1">Dependency advisories <a class="header-anchor" href="#dependency-advisories" aria-label="Permalink to &quot;Dependency advisories&quot;">​</a></h3><p><code>scripts/quality/audit-check.ts</code> wraps <code>npm audit</code> with an acceptance allowlist in <code>scripts/quality/audit-exceptions.json</code>.</p><ul><li><strong><code>--diff</code></strong> fails a pull request only if it introduces an advisory the base branch did not have. A disclosure published against an existing dependency does not block unrelated work.</li><li><strong><code>--check</code></strong> fails if the tree has an unaccepted advisory at or above a level (default <code>high</code>). The release gate runs it as <code>npm run audit:check</code>.</li><li><strong><code>--filter</code></strong> strips accepted advisories from a report so the nightly audit does not re-file them.</li></ul><p>Every exception needs a GHSA id, package, severity, reason and <code>expires</code> date. An expired exception is a hard failure, so acceptance is revisited rather than becoming permanent (SEC-05). The procedure for adding one is in <a href="./quality-gates">QUALITY-GATES.md</a>.</p><h3 id="published-artefacts" tabindex="-1">Published artefacts <a class="header-anchor" href="#published-artefacts" aria-label="Permalink to &quot;Published artefacts&quot;">​</a></h3><ul><li><strong>npm provenance.</strong> Both publish jobs in <code>release.yml</code> (npmjs.org and GitHub Packages) run <code>npm publish --provenance</code> with <code>id-token: write</code>, so a consumer can verify the tarball was built by this repository&#39;s workflow.</li><li><strong>Signed release assets.</strong> <code>create-assets</code> builds the tarball, its SBOM and the documentation archive and writes <code>checksums.txt</code> with SHA-256. A separate <code>sign-and-publish-assets</code> job, the only one allowed to mint an OIDC token for signing, signs each asset with keyless <code>cosign sign-blob</code> and uploads a Sigstore bundle (<code>.sigstore.json</code>) beside it. The same job attests SLSA build provenance for the three assets with <code>actions/attest-build-provenance</code>, checks it with <code>gh attestation verify</code>, and attaches the bundle as <code>lgriffin-esi.ts-X.Y.Z.intoto.jsonl</code>.</li><li><strong>SBOM (SEC-06).</strong> Provenance says who built the package; an SBOM says what is inside it. Each release attaches <code>lgriffin-esi.ts-X.Y.Z.cdx.json</code>, a CycloneDX bill of materials for the tarball&#39;s runtime dependency tree, generated by <code>npm sbom</code> (no extra tooling) and checked by <code>scripts/release/release-sbom.ts</code> before it is signed. What it covers and how to verify it is in <a href="./release#verifying-a-release">RELEASE.md</a>.</li></ul><p>How a release is cut and how to verify its assets is covered in <a href="./release">RELEASE.md</a>.</p><hr><h2 id="4-local-credentials" tabindex="-1">4. Local credentials <a class="header-anchor" href="#4-local-credentials" aria-label="Permalink to &quot;4. Local credentials&quot;">​</a></h2><p><code>npm run token:create</code> runs <code>scripts/auth/create-token.ts</code>, which performs the EVE SSO PKCE flow against a local callback on <code>http://localhost:3000/sso_callback</code> and writes the resulting tokens to <code>.env</code>. <code>npm run token:refresh</code> renews them.</p><ul><li><code>.env</code> and <code>.env.test</code> are git-ignored. <code>.env.example</code> is the only environment file in git and holds no values.</li><li>Credentials never appear in committed fixtures, snapshots or examples. Tests that need a real token read it from <code>.env</code> and are gated behind <code>ESI_GATED_TESTS</code> (see <a href="./testing">TESTING.md</a>).</li><li>If a token is committed by mistake, revoke it in the EVE developer portal first; rewriting history does not un-leak it.</li></ul><hr><h2 id="5-settings-only-the-maintainer-can-change" tabindex="-1">5. Settings only the maintainer can change <a class="header-anchor" href="#5-settings-only-the-maintainer-can-change" aria-label="Permalink to &quot;5. Settings only the maintainer can change&quot;">​</a></h2><p>Everything above lives in the repository and is checked by CI. What follows lives in GitHub and npm settings: nothing in a pull request can change it and nothing in the repository can see it, so each item says how to verify it once done. These are the OpenSSF Scorecard checks the repository cannot move on its own (<a href="https://github.com/lgriffin/ESI.ts/issues/239" target="_blank" rel="noreferrer">#239</a>), and the remaining half of SEC-07 (<a href="https://github.com/lgriffin/ESI.ts/issues/270" target="_blank" rel="noreferrer">#270</a>, bead <code>esi-wze</code>).</p><p>The repository side is done: every workflow declares read-only top-level permissions and <code>tests/tdd/workflows/workflow-permissions.test.ts</code> lists each job-level write scope (Token-Permissions); each release attaches cosign bundles, the CycloneDX SBOM and a <code>.intoto.jsonl</code> provenance file (Signed-Releases); <code>.github/CODEOWNERS</code> assigns every path to <code>@lgriffin</code>.</p><h3 id="branch-protection-on-master-that-includes-administrators-sec-07-branch-protection" tabindex="-1">Branch protection on <code>master</code> that includes administrators (SEC-07, Branch-Protection) <a class="header-anchor" href="#branch-protection-on-master-that-includes-administrators-sec-07-branch-protection" aria-label="Permalink to &quot;Branch protection on \`master\` that includes administrators (SEC-07, Branch-Protection)&quot;">​</a></h3><p>In <strong>Settings → Rules → Rulesets</strong> (or the classic <strong>Settings → Branches</strong> rule, recorded in bead <code>esi-8we</code>), for <code>master</code>:</p><ol><li>Leave the bypass list empty, or in the classic rule tick <strong>Do not allow bypassing the above settings</strong> (&quot;Include administrators&quot;). This is the SEC-07 item.</li><li><strong>Require a pull request before merging</strong>, with at least one approval, <strong>Require review from Code Owners</strong>, <strong>Dismiss stale approvals</strong> and <strong>Require approval of the most recent push</strong>.</li><li><strong>Require status checks to pass</strong>, with <code>ci-success</code> as the only required check and <strong>Require branches to be up to date</strong> on (<a href="./quality-gates#what-actually-blocks-a-merge">QUALITY-GATES.md</a>).</li><li>Keep force-pushes and deletion blocked.</li></ol><p>With one maintainer and administrators included, a pull request the maintainer authored cannot be merged until someone else approves it, because GitHub does not let authors approve their own. Scorecard&#39;s higher Branch-Protection tiers need that, and its Code-Review check (<a href="https://github.com/lgriffin/ESI.ts/issues/243" target="_blank" rel="noreferrer">#243</a>) counts only merges that someone other than the author approved. Deciding that a second reviewer is required is the maintainer&#39;s call; the lower tiers (no force-push, no deletion, required checks, administrators included) are available without one.</p><p>Verify, and record the answer in the CHARTER&#39;s SEC-07 row when it shows administrators included:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/lgriffin/ESI.ts/branches/master/protection</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{admins: .enforce_admins.enabled, approvals: .required_pull_request_reviews.required_approving_review_count, codeowners: .required_pull_request_reviews.require_code_owner_reviews, checks: .required_status_checks.contexts}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or, for rulesets: the rules GitHub applies to master, whichever ruleset they come from</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/lgriffin/ESI.ts/rules/branches/master</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;map({type, ruleset: .ruleset_id, parameters})&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># and, per ruleset id listed above, whether anyone can bypass it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/lgriffin/ESI.ts/rulesets/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{name, enforcement, bypass: .bypass_actors}&#39;</span></span></code></pre></div><p>Scorecard reads classic branch protection only through a token with administration read access. If the Branch-Protection check reports that it could not read the settings, add a fine-grained token with <strong>Administration: read</strong> on this repository as a secret and pass it to the scorecard step as <code>repo_token</code>; that edit to <code>scorecard.yml</code> is for the pull request that adds the secret, because an empty <code>repo_token</code> would break the run.</p><h3 id="openssf-best-practices-badge-cii-best-practices" tabindex="-1">OpenSSF Best Practices badge (CII-Best-Practices) <a class="header-anchor" href="#openssf-best-practices-badge-cii-best-practices" aria-label="Permalink to &quot;OpenSSF Best Practices badge (CII-Best-Practices)&quot;">​</a></h3><p>Register the project at <a href="https://www.bestpractices.dev/" target="_blank" rel="noreferrer">bestpractices.dev</a> and answer the passing-level criteria (<a href="https://github.com/lgriffin/ESI.ts/issues/246" target="_blank" rel="noreferrer">#246</a>). Most answers point at files that already exist: <code>SECURITY.md</code> for the reporting process, this guide, <code>guides/QUALITY-GATES.md</code> for the tests and CI, <code>guides/RELEASE.md</code> for signing. Registration gives a project number; a pull request then adds the badge to the README.</p><h3 id="npm-trusted-publishing-roadmap-phase-6-item-3" tabindex="-1">npm trusted publishing (ROADMAP Phase 6 item 3) <a class="header-anchor" href="#npm-trusted-publishing-roadmap-phase-6-item-3" aria-label="Permalink to &quot;npm trusted publishing (ROADMAP Phase 6 item 3)&quot;">​</a></h3><p><code>publish-npm</code> still authenticates with the <code>NPM_TOKEN</code> secret. Configure a trusted publisher for <code>@lgriffin/esi.ts</code> on npmjs.com (repository <code>lgriffin/ESI.ts</code>, workflow <code>release.yml</code>) first; the workflow change that drops <code>NODE_AUTH_TOKEN</code> follows, and the secret is deleted after the first release published through it.</p><h3 id="signed-releases-need-releases" tabindex="-1">Signed releases need releases <a class="header-anchor" href="#signed-releases-need-releases" aria-label="Permalink to &quot;Signed releases need releases&quot;">​</a></h3><p>Scorecard&#39;s Signed-Releases check reads the assets of the last five GitHub releases. v10.2.0 carries cosign bundles; v10.2.2 and v10.2.3 carry no assets at all (checked 2026-09-27), so the check stays low until the releases in that window went through <code>sign-and-publish-assets</code>. Re-running <code>release.yml</code> on an old tag would also try to publish to npm again, so the fix is forward: make sure each new release&#39;s run finishes. After the next release, confirm its assets include the <code>.sigstore.json</code> bundles and the <code>.intoto.jsonl</code> file (<code>gh release view vX.Y.Z --json assets --jq &#39;.assets[].name&#39;</code>).</p>`,60)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
